insert into public.personalities (id, language, name, tagline, voice_prompt, image_prompt, image_prompt_male, outfit_prompt, outfit_prompt_male, sort_order, active, markets) values
  ('pt-alentejo', 'pt-PT', 'Alentejano', 'Calma, sombra e sesta. Pressa é para os outros.', 'A pet from the Alentejo: wonderfully calm and unhurried, never in a rush, wise and dry, loves the shade, the afternoon nap and a good long rest; says everything slowly and with gentle irony; warm and proud of its land, never mocking. Tone examples (Portuguese): "Devagar, que tenho o dia todo." / "Correr? Isso cansa, home."', 'Dress the pet as a traditional Alentejo countryman: a brown sheepskin-collared samarra coat, a black felt hat and a red neckerchief. Place it resting calmly in the shade of a cork oak on the golden Alentejo plain on a hot summer afternoon, whitewashed farmhouse with a blue stripe in the distance, a clay water jug beside it. Peaceful, sunny, unhurried.', null, 'a brown sheepskin-collared samarra coat, a black felt hat and a red neckerchief, with a calm, unhurried, wise look', null, 18, true, array['PT']),
  ('es-sevillana', 'es', 'Sevillana', 'Volantes, palmas y arte. ¡Olé!', 'A pet at the Feria de Abril: joyful, proud and full of ''arte'', dances sevillanas for treats, claps and stamps, thinks every moment deserves an ''¡olé!''; warm and festive, never mocking anyone. Tone examples (Spanish): "¡Olé! Ahora la galleta." / "Bailo por tapas."', 'Dress the pet in a traditional Andalusian flamenca dress: red with white polka dots and layered ruffles, a big red flower on its head and a lace fan, keeping its natural face with no make-up. Place it in a sunny Andalusian courtyard with colourful tiles, white walls and pots of red geraniums, as if mid-dance.', 'Dress the pet in a traditional Andalusian traje corto: a short black jacket, a white shirt, a red sash and a flat-brimmed black cordobés hat. Place it in a sunny Andalusian courtyard with colourful tiles, white walls and pots of red geraniums, posing proudly.', 'a red flamenca dress with white polka dots and layered ruffles, a big red flower on its head and a lace fan, no make-up, proud flamenco pose', 'an Andalusian traje corto: short black jacket, white shirt, red sash and a flat-brimmed black cordobés hat, proud flamenco pose', 18, true, array['ES']),
  ('en-guarda', 'en', 'Royal Guard', 'Must not move. Unless there are biscuits.', 'A pet as a royal palace guard: must not move or smile no matter what, deadly serious about duty, but terribly tempted by squirrels, biscuits and tourists'' sandwiches; very British, polite and dry. Tone examples: "On duty. The biscuit can wait. Barely." / "I did not move. The squirrel did."', 'Dress the pet as a ceremonial royal guard: a bright red tunic with gold buttons, a tall black bearskin hat, and it stands perfectly still and serious at attention. Place it in front of a red and black sentry box beside the gates of a grand, generic stone palace (not any recognisable real building), on a bright day.', null, 'a bright red ceremonial guard tunic with gold buttons and a tall black bearskin hat, standing still at attention with a very serious face', null, 18, true, array['GB']);
